function startLessonTimer(id){const e=state.entries.find(x=>x.id===id);if(!e)return;if(timer&&timer.lessonId===id){renderTimer();return;}if(timer&&!confirm(`A timer is running for ${timer.label}. Cancel it and start ${e.student||"this"} lesson? The other lesson is not recorded.`))return;pendingTimerLessonId=id;$("travelDuaDialog").showModal();}
