$("packageForm").addEventListener("submit",ev=>{ev.preventDefault();const s=state.students.find(x=>x.id===profileId),h=num($("pkgHours").value);if(!s||h<=0)return;state.packages=[...pkgs(),{id:uid(),student:s.name,name:$("pkgName").value.trim(),date:$("pkgDate").value,hours:h,amount:num($("pkgAmount").value),paid:$("pkgPaid").checked,notes:$("pkgNotes").value.trim()}];save();$("packageDialog").close();toast("Package added");});
$("cloudConnect").onclick=cloudConnect;$("cloudNow").onclick=()=>cloudSync();$("cloudDisconnect").onclick=()=>{if(confirm("Stop syncing on this device? Your records stay here and in the cloud."))cloudOff();};
