$("exportLog").onclick=exportLog;$("exportStudents").onclick=exportStudents;
$("importCleanup").onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const d=JSON.parse(await f.text());if(confirm("This merges students and changes names on this device. Have you made a backup first?"))applyCleanup(d);}catch(err){toast("Nothing changed: "+err.message);}e.target.value="";};
function validBackup(d){return !!d&&Array.isArray(d.entries)&&Array.isArray(d.students)&&d.entries.every(x=>x&&x.id&&/^\d{4}-\d{2}-\d{2}$/.test(x.date)&&typeof x.type==="string")&&d.students.every(x=>x&&x.id&&typeof x.name==="string")&&(d.packages==null||Array.isArray(d.packages)&&d.packages.every(p=>p&&p.id&&typeof p.student==="string"&&Number(p.hours)>0))&&(d.fullTime==null||Array.isArray(d.fullTime)&&d.fullTime.every(x=>x&&typeof x.legacy_student_id==="string"&&x.legacy_student_id.trim()&&typeof x.student_name==="string"));}
function keepCopy(name){try{localStorage.setItem(DB_KEY+"-before-"+name,JSON.stringify({...snapshot(),copySaved:new Date().toISOString()}));renderRecovery();return true;}catch{return false;}}
function useBackup(d){state={entries:d.entries,students:d.students};if(d.prayer&&typeof d.prayer==="object")state.prayer=d.prayer;if(d.work&&typeof d.work==="object")state.work=d.work;if(Array.isArray(d.packages))state.packages=d.packages;if(Array.isArray(d.fullTime))window.DrivingLogFullTime?.replace(d.fullTime);fillPrayerForm();fillWorkForm();save();}
// Replace the data with d, keeping the current data as a safety copy first.
function replaceData(d,question){const cloud=cloudCfg()?" Cloud sync is on, so the cloud copy will be replaced too.":"";if(!confirm(question+cloud+" The current data is kept as a safety copy."))return false;if(hasData(snapshot())&&!keepCopy("restore")&&!confirm("There is no room to keep a safety copy. Download a backup first. Continue without a safety copy?"))return false;useBackup(d);return true;}
$("restoreBackup").onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const d=JSON.parse(await f.text());if(!validBackup(d))throw Error("Invalid backup");if(replaceData(d,"Replace current app data with this backup?"))toast("Backup restored");}catch(err){toast("Could not restore backup: "+err.message);}e.target.value="";};
const COPIES=[["before-upgrade","Before the v1.19 upgrade"],["before-restore","Before the last restore"],["before-sync","Before the first cloud sync"],["damaged","Saved data that could not be read"]];
const readCopy=k=>{try{return localStorage.getItem(DB_KEY+"-"+k);}catch{return null;}};
function renderRecovery(){const rows=COPIES.map(([k,label])=>{const raw=readCopy(k);if(!raw)return"";let d=null;try{d=JSON.parse(raw);}catch{}const ok=validBackup(d),when=ok&&d.copySaved&&!isNaN(new Date(d.copySaved))?" · "+new Date(d.copySaved).toLocaleString("en-GB",{dateStyle:"medium",timeStyle:"short"}):"",info=ok?`${d.entries.length} records, ${d.students.length} students${when}`:"Can only be downloaded";return `<div class="recoveryrow"><span><b>${esc(label)}</b><br><small>${esc(info)}</small></span><button type="button" class="btn secondary" data-copydl="${k}">Download</button>${ok?`<button type="button" class="btn secondary" data-copyuse="${k}">Put back</button>`:""}<button type="button" class="btn ghost" data-copydel="${k}">Delete</button></div>`;}).join("");$("recoveryBox").classList.toggle("hidden",!rows);$("recoveryList").innerHTML=rows;
 document.querySelectorAll("[data-copydl]").forEach(b=>b.onclick=()=>{const raw=readCopy(b.dataset.copydl);if(raw)download(`DrivingLogPro_${b.dataset.copydl}.json`,raw,"application/json");});
 document.querySelectorAll("[data-copyuse]").forEach(b=>b.onclick=()=>{let d=null;try{d=JSON.parse(readCopy(b.dataset.copyuse));}catch{}if(validBackup(d)&&replaceData(d,"Put this safety copy back?"))toast("Safety copy put back");});
 document.querySelectorAll("[data-copydel]").forEach(b=>b.onclick=()=>{if(confirm("Delete this safety copy? This cannot be undone.")){try{localStorage.removeItem(DB_KEY+"-"+b.dataset.copydel);}catch{}renderRecovery();}});}
$("clearData").onclick=()=>{if(confirm("Permanently delete ALL Driving Log Pro data from this browser, including the Full-Time Students register? Export a full backup first. Cloud sync on this device will be disconnected; the private cloud copy will be kept.")){cloudOff();state={entries:[],students:[]};window.DrivingLogFullTime?.clear();save();toast("All local data deleted, including Full-Time Students");}};
