{let lastY=scrollY;addEventListener("scroll",()=>{const y=scrollY,fab=$("newLessonBtn");if(y>lastY+6&&y>120)fab.classList.add("fabhide");else if(y<lastY-6||y<120)fab.classList.remove("fabhide");lastY=y;},{passive:true});}
