// Ask the browser not to clear the records when space is low.
async function askPersist(){try{if(!navigator.storage?.persist)return;let ok=await navigator.storage.persisted();if(!ok&&state.entries.length)ok=await navigator.storage.persist();$("storageNote").textContent=ok?"This browser keeps the app's data safe from automatic clean-up.":"This browser may clear the app's data when space is low. Keep downloading backups.";}catch{}}
{const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==="MacIntel"&&navigator.maxTouchPoints>1),home=navigator.standalone===true||matchMedia("(display-mode: standalone)").matches;let seen=false;try{seen=!!localStorage.getItem(DB_KEY+"-ios-tip");}catch{}$("iosBanner").classList.toggle("hidden",!ios||home||seen);$("iosBannerClose").onclick=()=>{try{localStorage.setItem(DB_KEY+"-ios-tip","1");}catch{}$("iosBanner").classList.add("hidden");};}
// If the app stays open past midnight, move "today" to the new day.
let shownDay=dateISO(new Date());function checkDay(){const t=dateISO(new Date());if(t===shownDay){renderNext();renderPrayerLine(t);bindRecords();return;}if(cal.day===shownDay){const n=new Date();cal.y=n.getFullYear();cal.m=n.getMonth();cal.day=t;}shownDay=t;render();}
setInterval(checkDay,60000);document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")checkDay();});
